const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Home-chef and cloud kitchen menu auditor. Validates 14-digit FSSAI license syntax, scans dishes for the 8 major allergens, checks mandatory oil/spice disclosure, and verifies hygiene standards.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"kitchenName":"Meera's Homemade Kitchen","fssaiLicense":"21223180000492","complianceVerdict":"APPROVED_WITH_CAUTIONS","fssaiStatus":"VALID_FORMAT","allergenAudit":[{"dish":"Shahi Paneer","allergensIdentified":["DAIRY","TREE_NUTS (Cashew)"],"warningSeverity":"MODERATE"},{"dish":"Methi Thepla","allergensIdentified":["GLUTEN","SESAME"],"warningSeverity":"LOW"},{"dish":"Walnut Halwa","allergensIdentified":["TREE_NUTS (Walnut)","DAIRY"],"warningSeverity":"HIGH"}],"missingDisclosures":["Must declare refined peanut oil usage explicitly for fried snacks."],"foodSafetyAdvisory":"Ensure packaging seals have manufacturing date and 24-hour consume-by label."}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"kitchenName":"Meera's Homemade Kitchen","fssaiLicense":"21223180000492","complianceVerdict":"APPROVED_WITH_CAUTIONS","fssaiStatus":"VALID_FORMAT","allergenAudit":[{"dish":"Shahi Paneer","allergensIdentified":["DAIRY","TREE_NUTS (Cashew)"],"warningSeverity":"MODERATE"},{"dish":"Methi Thepla","allergensIdentified":["GLUTEN","SESAME"],"warningSeverity":"LOW"},{"dish":"Walnut Halwa","allergensIdentified":["TREE_NUTS (Walnut)","DAIRY"],"warningSeverity":"HIGH"}],"missingDisclosures":["Must declare refined peanut oil usage explicitly for fried snacks."],"foodSafetyAdvisory":"Ensure packaging seals have manufacturing date and 24-hour consume-by label."} } }];
}
